// Synthetic passage corpus of issues #79-#82 and #87, as generated by store-exclude.js: passages of 150-250 words
// drawn from a Zipf-distributed 40k-word vocabulary, with `text`, `section`, `title`, `itemKey` (string), `page`,
// `year` (number) and `collection` (enum), about 80 passages per item, and optionally a random unit vector.

export const VOCABULARY = 40_000
export const BATCH = 500

export const schema = {
  text: 'string',
  section: 'string',
  title: 'string',
  itemKey: 'string',
  page: 'number',
  year: 'number',
  collection: 'enum'
}

// Deterministic PRNG (mulberry32)
export function prng(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const SYLLABLES = ['ka', 'lo', 'mi', 'ne', 'ru', 'sa', 'ti', 'vo', 'ze', 'pa', 'do', 'fi', 'gu', 'he', 'ja', 'be']

function makeWord(i) {
  let word = ''
  let n = i + 16
  while (n > 0) {
    word += SYLLABLES[n % 16]
    n = Math.floor(n / 16)
  }
  return word
}

/** The vocabulary, most frequent word first. */
export const words = Array.from({ length: VOCABULARY }, (_, i) => makeWord(i))

/** Returns a function that samples a word of the vocabulary with Zipf (s = 1) probabilities. */
export function zipfSampler(random) {
  const cdf = new Float64Array(VOCABULARY)
  let total = 0
  for (let i = 0; i < VOCABULARY; i++) {
    total += 1 / (i + 1)
    cdf[i] = total
  }

  return () => {
    const target = random() * total
    let lo = 0
    let hi = VOCABULARY - 1
    while (lo < hi) {
      const mid = (lo + hi) >>> 1
      if (cdf[mid] < target) lo = mid + 1
      else hi = mid
    }
    return words[lo]
  }
}

/** Yields batches of `BATCH` passages (the same passages as store-exclude.js for the same `docs`). */
export function* passages(docs, { dimensions = 0, batch = BATCH, seed = 81 } = {}) {
  const random = prng(seed)
  const sampleWord = zipfSampler(random)

  function sentence(length) {
    const parts = new Array(length)
    for (let i = 0; i < length; i++) parts[i] = sampleWord()
    return parts.join(' ')
  }

  function vector() {
    const v = new Array(dimensions)
    let norm = 0
    for (let i = 0; i < dimensions; i++) {
      v[i] = random() * 2 - 1
      norm += v[i] * v[i]
    }
    norm = Math.sqrt(norm)
    for (let i = 0; i < dimensions; i++) v[i] /= norm
    return v
  }

  for (let start = 0; start < docs; start += batch) {
    const out = []
    for (let i = start; i < Math.min(start + batch, docs); i++) {
      const doc = {
        id: `p${i}`,
        text: sentence(150 + Math.floor(random() * 101)),
        section: sentence(3),
        title: sentence(6),
        itemKey: `ITEM${Math.floor(i / 80)}`,
        page: 1 + (i % 80),
        year: 1990 + Math.floor(random() * 35),
        collection: `col${Math.floor(random() * 12)}`
      }
      if (dimensions) doc.embedding = vector()
      out.push(doc)
    }
    yield out
  }
}
